# Check small cases for x^z + 1 | (x+1)^y
# Constraints: 1 <= x, y, z < 100

def check_good(x, y, z):
    numerator = (x + 1)**y
    denominator = x**z + 1
    if numerator % denominator == 0:
        return True
    return False

# Test edge case x=1
count_x1 = 0
for y in range(1, 100):
    for z in range(1, 100):
        if check_good(1, y, z):
            count_x1 += 1
# For x=1, denominator is 2. (1+1)^y = 2^y. 2 | 2^y is always true for y>=1.
# print(f"Count for x=1: {count_x1}") # Expected: 99*99 = 9801

# Test edge case z=1
count_z1 = 0
for x in range(1, 100):
    for y in range(1, 100):
        if check_good(x, y, 1):
            count_z1 += 1
# For z=1, denominator is x+1. (x+1)^y / (x+1) is always an integer for y>=1.
# print(f"Count for z=1: {count_z1}") # Expected: 99*99 = 9801

# Check overlap x=1, z=1
count_overlap = 0
for y in range(1, 100):
    if check_good(1, y, 1):
        count_overlap += 1
# Expected: 99

# Total approximate (19503)
# print(f"Approximate total: {count_x1 + count_z1 - count_overlap}")

def is_good_triple(x, y, z):
    # We check if (x+1)^y is divisible by x^z + 1
    numerator = (x + 1)**y
    denominator = x**z + 1
    if denominator == 0:
        return False # Should not happen for positive integers x, z
    return numerator % denominator == 0

count = 0
limit = 30
for x in range(1, limit):
    for y in range(1, limit):
        for z in range(1, limit):
            if is_good_triple(x, y, z):
                count += 1
print(count)

